reference_solution.phones.py:
_REMOVED = set(" .-()")
_DIGITS = set("0123456789")


def normalize_phone(raw):
    text = "".join(ch for ch in raw if ch not in _REMOVED)
    if text.startswith("+"):
        text = text[1:]
    if not text or not set(text) <= _DIGITS:
        raise ValueError("not a US phone number: %r" % raw)
    if len(text) == 11 and text[0] == "1":
        text = text[1:]
    if len(text) != 10:
        raise ValueError("not a US phone number: %r" % raw)
    return "+1" + text

reference_solution.finance.py:
def future_value(principal, annual_rate, years, periods_per_year):
    rate = annual_rate / 100.0
    n = periods_per_year
    value = principal * (1 + rate / n) ** (n * years)
    return round(value, 2)

